package com.zhuzi.app.data

/** Une phrase d'exemple : en chinois, en pinyin, et traduite. */
data class Example(val hanzi: String, val pinyin: String, val french: String, val english: String, val russian: String) {
    fun meaning(lang: Lang): String = when (lang) {
        Lang.FR -> french
        Lang.EN -> english
        Lang.RU -> russian
        Lang.BN -> Bn.t(english)
    }
}

/** Les phrases d'exemple de tous les mots (HSK 1 et HSK 2). */
val examples: Map<String, Example> by lazy { hsk1Examples + hsk2Examples + hsk3Examples + hsk3bExamples }

